"""带字母的界址点编号：A1–A4、B1–B10 是同一宗的两块（版式取自金普新区 2025-03-12 公示，姓名已替换）。"""
from rs_verify import registry_parse as R

FMT_D = '养殖面积 申请水域、 申请水域、滩涂   \n序号 申请人 养殖方式   \n（公顷） 滩涂位置 地理坐标   \nA1 39°15′11.7800″ 122°15′40.8000″   \nA2 39°15′08.0500″ 122°15′42.7800″   \nA3 39°15′13.2900″ 122°16′00.6200″   \nA4 39°15′17.0100″ 122°15′58.4900″   \nB1 39°15′16.9000″ 122°15′59.7900″   \nB2 39°15′06.5600″ 122°16′05.7100″   \nB3 39°14′57.8500″ 122°16′08.6800″   \n71 甲 59.7893 筏吊式、滩涂底播 杏树街道   \nB4 39°14′59.3700″ 122°16′35.2000″   \nB5 39°15′05.5500″ 122°16′29.4500″   \nB6 39°15′11.0900″ 122°16′30.3000″   \nB7 39°15′11.5400″ 122°16′39.3900″   \nB8 39°15′27.9100″ 122°16′27.3900″   \nB9 39°15′21.6500″ 122°16′07.7800″   \nB10 39°15′19.2500″122°16′08.0400″   \n  \n1 39°17′05.8900″ 122°17′52.0800″   \n2 39°17′05.4400″ 122°18′05.6400″   \n72 乙 12.1153 筏吊式 杏树街道   \n3 39°16′54.2100″ 122°18′01.3700″   \n4 39°16′54.3700″ 122°17′46.3600″   \n'


def test_lettered_parts_are_one_parcel():
    rows = R.parse_text(FMT_D, "t")
    assert len(rows) == 2 and all(r["qc"] == "ok" for r in rows)
    assert len(rows[0]["rings"]) == 2 and rows[0]["n_pts"] == 14 and rows[0]["area_decl_ha"] == 59.7893
    assert rows[0]["raft_visible"] and rows[1]["area_decl_ha"] == 12.1153
